INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43627, 'Золотая монета Тралла', 'Покойся в мире, Гром, старый друг…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43628, 'Золотая монета леди Джайны Праудмур', 'Артас, любовь моя, пожалуйста, вернись!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43629, 'Золотая монета Утера Светоносного', 'Юному Артасу следует научиться терпению. Одного могущества мало… Я буду молиться, чтобы он со временем научился действовать без применени');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43630, 'Золотая монета Тириона Фордринга', 'Хочу, чтобы мой Таэлан вырос достаточно сильным, чтобы защищать тех, кто ему небезразличен!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43631, 'Золотая монета Терона', 'Желания – забава для глупцов. Прими эту монету как плату за свое драгоценное Око.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43632, 'Золотая монета Сильваны Ветрокрылой', 'Надеюсь, мы с сестрами вырастем и вместе выйдем замуж… Эта монета кажется очень древней.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43633, 'Золотая монета принца Кель''таса Солнечного Скитальца', 'Эта юная волшебница, Джайна, довольно привлекательна для человеческой девушки. Надеюсь, она уже заметила, как я силен и импозантен.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43634, 'Золотая монета леди Катраны Престор', 'Слушай, ты, фонтанишко для желаний! Быстро отдай мне всю свою силу, а не то тебе не поздоровится!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43635, 'Золотая монета Кел''Тузада', 'Иногда… иногда мне хочется, чтобы кто-нибудь просто подошел ко мне и крепко-крепко обнял.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43636, 'Золотая монета Хроми', 'Я желаю, чтобы кто-нибудь хоть раз обратился ко мне нормально, не отпустив идиотскую шуточку про гномов и путешествия во времени...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43637, 'Золотая монета Бранна Бронзоборода', 'Здесь был Бранн Бронзобород.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43638, 'Золотая монета Аругала', 'Вот мое желание: удалиться на покой в маленький, уютный домик, и чтобы сопровождали меня только верные собаки.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43639, 'Золотая монета Артаса', 'Итак, у меня есть королевство и земли. Чего еще желать? Ледяной трон?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43640, 'Золотая монета Архимонда', 'Хотел бы я знать, как ты избежал моего гнева, фонтанишко.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43641, 'Золотая монета Андуина Ринна', 'Я хочу скорее вырасти! Кажется, я просто застрял на десятилетнем возрасте!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43643, 'Серебряная монета принца Магни Бронзоборода', 'Надеюсь, отец и братья переживут меня. Ну какой из меня король?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43644, 'Серебряная монета крестьянина', 'Экий я забывчивый! Совсем памяти не стало… Постой-ка, я же, вроде, уже бросил туда одну монету?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43645, 'Погнутый рыболовный крючок', 'Похоже, кто-то пытался ловить рыбу в этом фонтане. Интересно, кому пришла в голову такая дурацкая мысль?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43646, 'Золотая рыбка из фонтана', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43647, 'Мерцающий гольян', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43650, 'Ржавый ключ от тюрьмы', 'Напоминает ключ, которым открывали затонувшие сундуки с сокровищами.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43651, 'Удочка Умейки', 'Вас переполняет восторг от одного взгляда на эту удочку. Кажется, это самая удивительная вещь, которую вы когда-либо видели в своей жизни.');
