INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43658, 'Ржавый напильник', 'Слегка с прозеленью...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43659, 'Окровавленная тюремная заточка', 'Рабочий конец этой заточки наводит вас на мысль о том, что ее обладатель неплохо заработал в этом году.');
