INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43665, 'Разбитое сердце Керистразы', 'Трагический конец печальной истории. Если бы только Керистраза не сошла с ума от того, как обошелся с ней Малигос…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43666, 'Фолиант адского огня', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43667, 'Книга хитрых советов', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43668, 'Устройство для настройки силовых линий', 'Вы не знаете, что и думать. Эта штучка явно переполнена тайной магией, но как может такая маленькая вещица быть настолько мощной?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43669, 'Медальон Усопшей королевы', 'Единственное воспоминание, оставшееся у короля Имирона о его возлюбленной, королеве Ангербоде.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43670, 'Заколдованный амулет пророка', 'Похоже, со смертью хозяина вся магия из него ушла.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43671, 'Символ взрыва трупа', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43672, 'Символ мора', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43673, 'Символ воскрешения мертвых', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43674, 'Символ порыва', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43675, 'Серебряная монета Фэндрала Оленьего Шлема', 'Война Зыбучих Песков... Забыть бы о ней когда-нибудь...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43676, 'Серебряная монета чародея Доана', 'Ну почему ты меня не замечаешь! Аббендис, я всегда буду рядом с тобой. Прошу, хоть раз обрати на меня внимание...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43677, 'Серебряная монета главного механика Меггакрута', 'А как, интересно, работает этот фонтан? Может, и я такой же сделаю?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43678, 'Серебряная монета Антонидаса', 'Дай мне смелости, чтобы справиться с тем, что я могу сделать, дай мне сил принять то, на что я повлиять не могу, и дай мне мудрость, чтобы отлич');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43679, 'Серебряная монета Мурадина Бронзоборода', 'Пусть Священный Свет направляет нас в пути по суровому северу.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43680, 'Серебряная монета короля Вариана Ринна', 'Хотелось бы, чтобы неурядицы у нас дома улеглись как можно быстрее. Мне не хочется, чтобы кто-то пострадал.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43681, 'Серебряная монета короля Теренаса Менетила', 'Пусть мой сын Артас всегда действует в интересах своего народа!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43682, 'Серебряная монета короля Анастериана Солнечного Скитальца', 'Надеюсь, юный Кель\'тас сознает, что в один прекрасный день ему придется возглавить наш народ…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43683, 'Серебряная монета Кадгара', 'Туралион и Аллерия, где бы вы ни были, да пребудьте в добром здравии.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43684, 'Серебряная монета Медива', '<В вашей голове звенит созвучие трех нот, причем третью еле слышно за звоном двух других.>');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43685, 'Серебряная монета Майев Песни Теней', 'Где же Иллидан?');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43686, 'Серебряная монета Аллерии', 'Пусть мои сестры поймут, на что они способны, и пусть деяния Ветрокрылых прославят их имя в веках.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43687, 'Серебряная монета Эгвин', 'Хотелось бы мне, чтобы вы, маги, хоть иногда доставали головы из своих... книг.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43688, 'Документ из Саронитового карьера', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43689, 'Гроссбух Саронитового карьера', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43690, 'Расписание работ в Саронитовом карьере', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43691, 'Карта Саронитового карьера', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43693, 'Остатки колдунства Акали', 'Трудно поверить, что это всё, что осталось от некогда могучего бога-люторога.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43694, 'Утонувшая крыса', 'Похоже, на этот раз купание в супе не пошло ей на пользу.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43695, 'Наполовину полная бутылка заключенного лунного света', 'Также хорошо отчищает краску.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43696, 'Наполовину пустая бутылка заключенного лунного света', 'Также хорошо отчищает краску.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43697, 'Артефакт с родины натрезимов', 'Какое странное сооружение... Пожалуй, это самый причудливый объект, который когда-либо попадался вам в руки.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43698, 'Гигантская сточная крыса', 'Учит призывать этого спутника.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43699, 'Диск Проклятия Плоти', 'Что? На этой штуке записана информация? Где?! Тут ничего не написано!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43701, 'Медная монетка пехотинца', 'Хотелось бы мне поменяться местами с моим двоюродным братом и весь день беспечно таскать бревна...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43702, 'Медная монета Алонсуса Фаола', 'Надеюсь когда-нибудь наставить на путь света всех достойных людей и показать им, как важно чтить Три Добродетели.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43703, 'Медная монета Ансарема', 'Я желаю счастья и благополучия моей доченьке. Ей так одиноко здесь...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43704, 'Медная монета Аттумена', 'А можно седло поудобнее? А то скоро сидеть будет нечем.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43705, 'Медная монета Даната', 'Желаю, чтобы тролль умер... прямо СЕЙЧАС.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43706, 'Сверкающая медная монета Дорнаа', 'Желаю, чтобы этот подлец Артас шлепнулся в кучу магнатаврского навоза!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43707, 'Медная монета Эйтригга', 'Я желаю Тириону благополучно завершить свои дела в Нордсколе – или хотя бы с честью погибнуть в бою.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43708, 'Медная монета Иллинга Триаса', 'Быть разбойником очень нелегко. Я надеюсь когда-нибудь заняться своим любимым делом.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43709, 'Медная монета Фалстада Громового Молота', 'Я мечтаю дожить до следующей книги.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43710, 'Медная монета Генна', 'Ха! Фонтаны в Гилнеасе выполняют в десять раз больше желаний, чем эти!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43711, 'Медная монета Иниго', 'Вот если бы вернулся мой отец…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43712, 'Медная монета Краса', 'Я молюсь за моих братьев и сестер, что поныне страдают в глубинах Грим Батола. Я непременно освобожу их!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43713, 'Медная монета Крилла', 'Бубух. Не бубух? Хочу бубух. Давай, бубух! Эта монета, наверно, испортилась, совсем не взрывается.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43714, 'Медная монета Ландро Дальнострела', 'Не хочется бросать эту монетку…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43715, 'Медная монета Молока', 'Пусть хоть раз – это все, чего я прошу, хоть раз! – пусть девчонка проедется со мной...');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43716, 'Медная монета Мурчаля', 'Вот бы вода в Нордсколе была потеплее, а то я от нее в спячку впадаю.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43717, 'Медная монета принцессы Калии Менетил', 'Хочу, чтобы этот красавец, лорд Престор, меня заметил! А то он весь погружен в свои мечты…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43718, 'Медная монета рядового Маркуса Джонатана', 'Хочу когда-нибудь отрастить роскошные, длинные усы!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43719, 'Медная монета Саландрии', 'Когда-нибудь я стану могущественней всех этих магов!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43720, 'Медная монета оруженосца Роу', 'Надеюсь, со временем мне удастся добиться, чтобы меня перевели из Штормграда. Снова увидеть Серсею… В этом городе нет ничего хорошего.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43721, 'Медная монета Сталвана', 'Вы, маги, отказываетесь снабдить меня тем, что лишь приблизит неизбежный исход, ожидающий двух влюбленных, один из которых столь наивен, что');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43722, 'Медная монета Верисы', 'Асто\'ре да шан\'ре. Турус Фуло лл\'амаре, А\'Тала Адоре. Изера\'дуна…');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43723, 'Медная монета Варгота', 'Вот бы капитан Сандерс побыстрее привез мне вино!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43724, 'Небесное рубиновое кольцо', 'Кольцо? Честно говоря, оно больше похоже на ожерелье – как по размеру, так и по весу!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43725, 'Символ призрачного волка', '');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (43726, 'Бесполезная корона Ануб\'арака', 'Владыка склепа все еще носил ее, хотя и утратил свой королевский титул давным-давно, ибо поступил на службу к Королю-личу.');
