INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50730, 'Глоренцельг, священный клинок Серебряной Длани', 'Воплощение Света, сплоти наши ряды в борьбе с надвигающейся тьмой!');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50731, 'Аркус, большой посох Антонидаса', 'Шесть изысканных рун обрамляют навершие посоха.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50732, 'Прилив Крови, клинок агонии Кел''Тузада', 'Этот мир будет пылать.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50733, 'Фал''инраш, Защитник Кель''Таласа', 'Во имя солнечного света Талас''дин.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50734, 'Королевский скипетр Теренаса II', 'Несмотря на то, что скипетр сломан и поверхность его изъедена, на нем все еще можно различить королевскую печать Лордерона.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50735, 'Клятвохранитель, алебарда предводителя следопытов', 'В основание клинка вплавлен жуткий череп. Кровь въелась в поверхность металла, десятикратно выгравировав одно лишь слово: СТРАДАНИЕ.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50736, 'Падение Небес, крис вечной лжи', 'Жало лжи обагрено ненавистью, наследие льстивых речей – руины.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50737, 'Зов хаоса, топор королей Лордерона', 'Пусть наши враги услышат зов хаоса, и да будет он предвестником их смерти.');
INSERT INTO `locales_item` (`entry`, `name_loc8`, `description_loc8`) VALUES (50738, 'Митриос, наследие Бронзоборода', 'На поверхности, оскверненной Плетью, угадывается надпись: …поддержите мой клич, и от хора наших голосов содрогнется трон самого Короля-лич');
